/* Specialist service configuration and record transfer, retaining existing modules. */
YS.designerProfile||={type:'独立设计师',name:'陈知予设计',specialties:['全屋设计','墙面设计','灯光设计'],styles:['原木风','新中式','奶油风'],team:1};
YUI.serviceSpecialty='全部';
if(!YS.jobGateVersion){for(const pr of E.projects){let dep=[[pr.id+'-task-3'],[pr.id+'-task-3'],[pr.id+'-task-5'],[pr.id+'-yjjob-2-task'],[pr.id+'-task-5'],[pr.id+'-yjjob-4-task'],[pr.id+'-yjjob-2-task',pr.id+'-yjjob-5-task'],[pr.id+'-yjjob-6-task']];for(let i=0;i<8;i++){let t=E.tasks.find(t=>t.id===pr.id+'-yjjob-'+i+'-task');if(t&&!t.depends.length)t.depends=dep[i];}}YS.jobGateVersion=1;}
YS.airHistory||={};
const ysAir=yAirPanel;yAirPanel=function(){let html=ysAir(),past=YS.airHistory[E.activeProject]||[];return html+(past.length?`<section class="panel section-spaced"><h3>历史检测与复测记录</h3>${table(['日期 / 机构','甲醛 / TVOC','报告结论','归档凭证'],past.map(a=>[esc(a.date)+'<small>'+esc(a.lab)+'</small>',esc(a.hcho??'未记录')+' / '+esc(a.tvoc??'未记录'),esc(a.result),a.file?evidence([a.file]):'无附件']))}</section>`:'');};
const ysHome=renderHome;
renderHome=function(){let html=ysHome();if(state.role!=='designer')return html;let p=YS.designerProfile;return `<section class="specialist-profile"><div><span class="eyebrow">A PARTICULAR EYE, A CLEAR RESPONSIBILITY</span><h2>${esc(p.name)} · ${p.type}</h2><p>把专业方向与审美说清楚，让需要的人找到你。${p.team} 人 · 对外档案为本机演示资料。</p><div class="tags">${[...p.specialties,...p.styles].map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="button-row">${yf('编辑专业与品味','designer-profile')}${yf('发布专项服务','specialist-service')}${go('服务、案例与交付','services')}</div></div><aside><h3>${p.type==='设计工作室'?'工作室协作':'独立设计师协作'}</h3><p>全屋负责人统筹，墙面、地面、门窗、家具、灯光和软装分别明确交付物。每项服务单列修改次数、工期与保修范围。</p>${go('配置项目成员与分工','members')}</aside></section>`+html;};
const ysServices=renderServices;
function yServiceCategory(s){if(s.specialty)return s.specialty;for(const [needle,category]of [['灯光','灯光设计'],['软装','软装搭配'],['柜','收纳定制'],['户型','户型优化'],['局部','户型优化'],['材料','墙面设计']])if(s.name.includes(needle))return category;return '全屋设计';}
renderServices=function(){let all=E.services,filtered=YUI.serviceSpecialty==='全部'?all:all.filter(s=>yServiceCategory(s)===YUI.serviceSpecialty);E.services=filtered;let html;try{html=ysServices();}finally{E.services=all;}let head=`<section class="specialist-service-controls"><div><h2>专项服务，把交付边界写清楚</h2><p>专业分类、擅长风格、工期、修改次数和方案保修对应同一项服务。</p></div>${can('designer')?yprimary('＋ 发布专项设计服务','specialist-service'):''}</section><div class="community-topics">${['全部',...YD.specialties].map(t=>`<button class="${YUI.serviceSpecialty===t?'active':''}" data-y="service-category" data-id="${t}">${t}</button>`).join('')}</div>`;for(const s of filtered){let anchor='<h3>'+esc(s.name)+'</h3>';html=html.replace(anchor,anchor+`<div class="tags"><span class="tag">${yServiceCategory(s)}</span>${s.styles?`<span class="tag">${esc(s.styles)}</span>`:''}</div><p>方案修正 / 保修：${s.warrantyMonths?s.warrantyMonths+' 个月，待合同确认':'签约前单独约定'}</p>`);}return head+html;};
newViews.services=()=>renderServices();

Object.assign(YA,{
 'air-edit':()=>{if(!ensureRole('inspector','company'))return;let a=YS.air[E.activeProject]||{};openForm('登记检测与复测报告',[field('date','检测日期','date'),field('lab','检测机构'),field('hcho','甲醛 / mg/m³（未检测请留空）','text',[],{required:false}),field('tvoc','TVOC / mg/m³（未检测请留空）','text',[],{required:false}),field('odor','异味记录'),field('result','检测机构结论','select',['待核实','报告结论符合其适用要求','需整改与复测','无法判定']),field('note','方法、点位、报告编号、适用依据和复测安排','textarea',[],{wide:true}),field('file','报告文件 / 凭证（500 KB 内）','file')],a,d=>{for(const k of ['hcho','tvoc']){let value=String(d[k]??'').trim();if(value!==''&&(!Number.isFinite(Number(value))||Number(value)<0)){toast('检测实测值请填写非负数字，未检测留空');return false;}d[k]=value===''?'':Number(value);}if(a.date){YS.airHistory[E.activeProject]||=[];YS.airHistory[E.activeProject].push(structuredClone(a));}if(!d.file&&a.file)d.file=a.file;YS.air[E.activeProject]=d;audit('空气报告归档',d.lab+' · '+d.date+' · '+d.result);});},
 'designer-profile':()=>{if(!ensureRole('designer'))return;let p=YS.designerProfile;modal('我的专业方向与审美档案',`<form id="yunju-profile"><div class="form-grid"><label class="field">服务名称<input name="name" required value="${esc(p.name)}"></label><label class="field">组织方式<select name="type"><option ${p.type==='独立设计师'?'selected':''}>独立设计师</option><option ${p.type==='设计工作室'?'selected':''}>设计工作室</option></select></label><label class="field">团队人数<input name="team" type="number" min="1" max="200" required value="${p.team}"></label></div><fieldset><legend>专业方向（多选）</legend><div class="profile-check-grid">${YD.specialties.map(s=>`<label><input name="specialties" type="checkbox" value="${s}" ${p.specialties.includes(s)?'checked':''}>${s}</label>`).join('')}</div></fieldset><fieldset><legend>擅长风格（多选）</legend><div class="profile-check-grid">${YD.styles.map(s=>`<label><input name="styles" type="checkbox" value="${s.name}" ${p.styles.includes(s.name)?'checked':''}>${s.name}</label>`).join('')}</div></fieldset><button class="primary">保存本机档案</button></form>`,true);},
 'service-category':el=>{YUI.serviceSpecialty=el.dataset.id;render();},
 'specialist-service':()=>{if(!ensureRole('designer'))return;modal('发布专项设计服务',`<form id="yunju-specialist-service"><div class="form-grid"><label class="field">服务名称<input name="name" required placeholder="例如：客厅墙面与灯光深化"></label><label class="field">专业分类<select name="specialty">${YD.specialties.map(s=>`<option>${s}</option>`).join('')}</select></label><label class="field">擅长风格<select name="styles">${YD.styles.map(s=>`<option>${s.name}</option>`).join('')}</select></label><label class="field">参考价格 / 元<input name="price" type="number" required min="0" step="0.01"></label><label class="field">计价单位<select name="unit"><option>次</option><option>㎡</option><option>套</option></select></label><label class="field">交付周期 / 天<input name="days" type="number" required min="1" max="180" value="7"></label><label class="field">修改次数<input name="changes" type="number" required min="0" max="100" value="2"></label><label class="field">方案修正服务月数<input name="months" type="number" required min="1" max="240" value="12"></label></div><label class="field">交付物、尺寸依据与未包含项<textarea name="deliverable" required></textarea></label><label class="field">修正 / 保修范围及除外项<textarea name="coverage" required placeholder="区分原成果疏漏修正与新增设计需求"></textarea></label><p class="sample-note">参考价格与保修提案需纳入合同确认，不自动形成真实交易。</p><button class="primary">保存专项服务与保修提案</button></form>`,true);},
 'records-export':()=>{let data=new Blob([JSON.stringify({brand:'YUNJU',version:3,exported:new Date().toISOString(),state},null,2)],{type:'application/json'}),url=URL.createObjectURL(data),a=document.createElement('a');a.href=url;a.download='yunju-experience-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('体验记录已导出；包含你的本机项目资料，请自行妥善保存');},
 'records-import':()=>modal('导入云居体验记录',`<form id="yunju-transfer"><label class="field">选择此前导出的 JSON 文件<input type="file" name="file" accept=".json,application/json" required></label><label class="field"><span><input type="checkbox" name="replace" required> 用此文件替换当前浏览器的体验记录</span></label><p class="notice">只支持本平台导出的结构化体验记录。不同网站地址之间不会自动迁移浏览器数据；这里没有真实账户同步。</p><button class="primary">校验并导入</button></form>`)
});
const ysGuide=actions.guide;actions.guide=()=>{ysGuide();$('#modal-content').insertAdjacentHTML('beforeend',`<section class="section-spaced"><h3>保存或迁移体验记录</h3><p class="subtext">所有交互记录仅保存在当前浏览器；新地址、另一设备或清理缓存都可能改变可见记录。</p><div class="button-row">${yf('导出体验记录','records-export')}${yf('导入体验记录','records-import')}</div></section>`);};
const ysOrder=orderDetail;orderDetail=function(id){ysOrder(id);let o=E.orders.find(o=>o.id===id),host=$('#modal-content');if(!o||!host)return;host.insertAdjacentHTML('beforeend',`<section class="product-protection"><h3>这件商品的评价与保修</h3>${yRatingButton(o.product)}<p>${esc(productBy(o.product)?.warranty||'保修范围待正式确认')}</p>${yf('查看完整保修档案','go-warranty')}${yf('按原订单发起售后','support-open',id)}</section>`);};
const ysCounterpart=YA['support-counterpart'];YA['support-counterpart']=el=>{let current=YS.cases.find(c=>c.id===el.dataset.id);if(!current||!can(current.role,'company'))return ysCounterpart(el);ysCounterpart(el);let old=ecoFormJob.submit;ecoFormJob.submit=d=>{let result=old(d);if(result===false)return false;let t=E.tickets.find(t=>t.id===current.ticket);if(t){t.state='待确认';t.messages.push({role:state.role,text:'待确认方案：'+current.proposal,time:new Date().toISOString()});}return result;};};
const ysCustomer=renderCustomer;renderCustomer=function(){for(const c of YS.cases){let t=E.tickets.find(t=>t.id===c.ticket);if(!t)continue;if(t.state==='已完成')c.state='已确认解决';else if(t.state==='待确认'){c.state='待发起方确认';if(!c.proposal)c.proposal=t.messages.findLast(m=>m.role!==c.requester)?.text||'';}else if(t.state==='待分派'&&c.state==='已确认解决')c.state='已重新打开 · 待分派';}return ysCustomer();};newViews.customer=()=>renderCustomer();
// Comparison and other product-only dialogs receive the same source of ratings.
const ysModal=modal;modal=function(title,body,wide=false){ysModal(title,body,wide);let host=$('#modal-content');for(const card of host.querySelectorAll('.product-card'))if(!card.querySelector('.rating-chip')){let id=card.querySelector('[data-id]')?.dataset.id;if(productBy(id))card.insertAdjacentHTML('beforeend',yRatingButton(id));}};

document.addEventListener('submit',async e=>{let f=e.target;if(!['yunju-profile','yunju-specialist-service','yunju-transfer'].includes(f.id))return;e.preventDefault();e.stopImmediatePropagation();let d=new FormData(f);try{
 if(f.id==='yunju-profile'){if(!ensureRole('designer'))return;let specialties=d.getAll('specialties').filter(s=>YD.specialties.includes(s)),styles=d.getAll('styles').filter(s=>YD.styles.some(t=>t.name===s));if(!specialties.length||!styles.length)return toast('至少选择一个专业方向和一种擅长风格');YS.designerProfile={name:String(d.get('name')).trim(),type:String(d.get('type')),team:Number(d.get('team')),specialties,styles};audit('设计师档案','更新专业、风格与组织方式');yfinish('专业与品味档案已保存');}
 if(f.id==='yunju-specialist-service'){if(!ensureRole('designer'))return;let id=uid('specialist'),service={id,role:'designer',name:String(d.get('name')).trim(),specialty:String(d.get('specialty')),styles:String(d.get('styles')),price:Number(d.get('price')),unit:String(d.get('unit')),days:Number(d.get('days')),changes:Number(d.get('changes')),deliverable:String(d.get('deliverable')).trim(),warrantyMonths:Number(d.get('months')),state:'展示中'};E.services.unshift(service);YS.warranties.push({id:id+'-warranty',project:E.activeProject,type:'专项设计 · '+service.name,party:YS.designerProfile.name,role:'designer',months:service.warrantyMonths,scope:String(d.get('coverage')),excludes:'以双方确认的具体除外项为准，新增需求需另行约定',response:'签约前确认响应与修改交付时间',state:'待合同确认',start:'',end:'',confirmed:false});audit('专项设计服务',service.name+' · '+service.specialty);YUI.serviceSpecialty='全部';yfinish('专项服务及关联保修提案已保存');}
 if(f.id==='yunju-transfer'){let file=d.get('file');if(!file?.size||file.size>4*1024*1024)return toast('请选择 4 MB 内的记录文件');let parsed=JSON.parse(await file.text());if(parsed.brand!=='YUNJU'||parsed.version!==3||!parsed.state?.eco||!Array.isArray(parsed.state.eco.projects)||!Array.isArray(parsed.state.eco.yunju?.jobs)||!Object.hasOwn(roles,parsed.state.role))return toast('不是受支持的云居体验记录');localStorage.setItem('yunju-prototype-v1',JSON.stringify(parsed.state));location.reload();}
 }catch(err){toast(err.message||'保存失败，请检查填写');}},true);
ysave();render();
